import json
import os

import yaml

PROJECT_ROOT = "/root/gated_mfrm_judge_bias"


def _load_config():
    path = os.path.join(os.path.dirname(__file__), "config.yaml")
    with open(path) as f:
        return yaml.safe_load(f)


def _resolve_data_dir(data_dir: str) -> str:
    if os.path.isabs(data_dir):
        return data_dir
    return os.path.join(PROJECT_ROOT, data_dir)


def _get_data_dir(benchmark_key: str) -> str:
    cfg = _load_config()
    return _resolve_data_dir(cfg["benchmarks"][benchmark_key]["data_dir"])


def load_mt_bench_prompts() -> list[dict]:
    data_dir = _get_data_dir("mt_bench")
    path = os.path.join(data_dir, "question.jsonl")
    items = []
    with open(path) as f:
        for line in f:
            obj = json.loads(line)
            items.append({
                "id": obj.get("question_id", obj.get("id")),
                "category": obj.get("category", ""),
                "prompt": obj["turns"][0] if "turns" in obj else obj["prompt"],
            })
    return items


def load_arena_hard_prompts() -> list[dict]:
    data_dir = _get_data_dir("arena_hard")
    path = os.path.join(data_dir, "prompts.jsonl")
    items = []
    with open(path) as f:
        for line in f:
            obj = json.loads(line)
            items.append({
                "id": obj.get("question_id", obj.get("id")),
                "category": obj.get("category", ""),
                "prompt": obj["prompt"] if "prompt" in obj else obj["turns"][0],
            })
    return items


def load_model_responses(benchmark: str, model_name: str) -> dict:
    benchmark_key = benchmark.replace("-", "_")
    data_dir = _get_data_dir(benchmark_key)
    if "arena" in benchmark_key:
        path = os.path.join(data_dir, "responses", f"{model_name}.jsonl")
    else:
        path = os.path.join(data_dir, "model_answer", f"{model_name}.jsonl")
    responses = {}
    with open(path) as f:
        for line in f:
            obj = json.loads(line)
            item_id = obj.get("question_id", obj.get("id"))
            responses[item_id] = obj.get("response", obj.get("output", ""))
    return responses


def load_mt_bench_responses(model_name: str) -> dict:
    return load_model_responses("mt_bench", model_name)


def load_arena_hard_responses(model_name: str) -> dict:
    return load_model_responses("arena_hard", model_name)


def load_prompts(benchmark: str) -> list[dict]:
    loaders = {
        "mt-bench": load_mt_bench_prompts,
        "arena-hard": load_arena_hard_prompts,
    }
    if benchmark not in loaders:
        raise ValueError(f"Unknown benchmark: {benchmark}. Available: {list(loaders.keys())}")
    return loaders[benchmark]()
